import yfinance as yf
import pandas as pd

SYMBOLS = {
    'GOLD': 'GC=F', 'SILVER': 'SI=F', 'COPPER': 'HG=F',
    'CRUDE_OIL': 'CL=F', 'NATURAL_GAS': 'NG=F',
    'CORN': 'ZC=F', 'WHEAT': 'ZW=F', 'SOYBEANS': 'ZS=F',
    'COFFEE': 'KC=F', 'SUGAR': 'SB=F', 'COTTON': 'CT=F'
}

def fetch_commodity_prices(symbols, period='3mo', interval='1d'):
    tickers = list(symbols.values())
    data = yf.download(tickers, period=period, interval=interval, group_by='ticker')
    return data

def get_latest_prices(symbols):
    results = {}
    for name, sym in symbols.items():
        t = yf.Ticker(sym)
        info = t.fast_info
        results[name] = {
            'price': info.last_price,
            'prev_close': info.previous_close,
            'change_pct': ((info.last_price - info.previous_close) / info.previous_close * 100) if info.previous_close else 0
        }
    return results

prices = get_latest_prices(SYMBOLS)
for name, p in prices.items():
    print(f"{name}: ${p['price']:.2f} ({p['change_pct']:+.2f}%)")
